S = "Hakeem Force Academy"
QS = [
(S, "What is the closest meaning of the word abundant?", ["Scarce", "Plentiful", "Tiny", "Costly"], 1, "Abundant means existing in large quantities. Plentiful is the closest synonym.", "The opposite of abundant is scarce.", 1),
(S, "What is the closest meaning of the word collaboration?", ["Competition", "Argument", "Cooperation", "Separation"], 2, "Collaboration means working together with others toward a common goal. Cooperation has the closest meaning.", "The word collaborate comes from Latin meaning to labour together.", 1),
(S, "What is the closest meaning of the word compassion?", ["Sympathy", "Anger", "Jealousy", "Pride"], 0, "Compassion is a feeling of concern and pity for the suffering of others. Sympathy is the closest meaning.", "Its opposite is cruelty or ruthlessness.", 1),
(S, "What is the closest meaning of the word extensive?", ["Narrow", "Brief", "Hidden", "Widespread"], 3, "Extensive means covering a large area or having a wide range. Widespread is the closest meaning.", "The opposite of extensive is limited.", 1),
(S, "What is the closest meaning of the word inhabitant?", ["Visitor", "Resident", "Traveller", "Stranger"], 1, "An inhabitant is a person who lives permanently in a place. Resident has the same meaning.", "The word comes from Latin inhabitare, meaning to dwell in.", 1),
(S, "What is the closest meaning of the word juvenile?", ["Elderly", "Wise", "Youthful", "Weak"], 2, "Juvenile refers to a young person or something belonging to young people. Youthful is the closest meaning.", "A juvenile court deals with offenders below the adult age.", 1),
(S, "What is the closest meaning of the word slackness?", ["Looseness or laziness", "Strictness", "Speed", "Strength"], 0, "Slackness means lack of tightness, energy or care. Looseness or laziness fits best.", "Slack is the opposite of taut.", 1),
(S, "What is the closest meaning of the word voyage?", ["Meal", "Journey", "Rest", "Battle"], 1, "A voyage is a long journey, especially by sea or in space. Journey is the closest meaning.", "The word voyage comes from Old French voiage.", 1),
(S, "What is the closest meaning of the word consent?", ["Refusal", "Doubt", "Permission", "Delay"], 2, "Consent means agreement or permission to do something.", "The opposite of consent is dissent.", 1),
(S, "What is the special unstitched cloth worn by pilgrims during Hajj called?", ["Ihram", "Jubba", "Shalwar", "Burqa"], 0, "Ihram is the two-piece unstitched white cloth worn by male pilgrims during Hajj and Umrah. Wearing it begins the state of ihram.", "Women pilgrims wear ordinary modest clothing and do not wear a special unstitched sheet.", 2),
(S, "What is the combination of the upper house and lower house of a legislature called?", ["Cabinet", "Parliament", "Judiciary", "Secretariat"], 1, "The legislature made up of the upper and lower houses is called Parliament. In Pakistan it is the Majlis-e-Shoora.", "Pakistan's Parliament consists of the National Assembly and the Senate together with the President.", 1),
(S, "Which is the correct spelling?", ["Acommodation", "Accomodation", "Accommodation", "Acomodation"], 2, "Accommodation is spelled with double c and double m.", "A tip is that it has two c and two m.", 1),
(S, "Which is the correct spelling?", ["Beginning", "Begining", "Beginnning", "Beggining"], 0, "The final consonant n is doubled when adding ing to begin, giving beginning.", "Similar doubling occurs in running and swimming.", 1),
(S, "What is the currency of Belarus?", ["Belarusian ruble", "Hryvnia", "Zloty", "Lev"], 0, "Belarus uses the Belarusian ruble (code BYN).", "The hryvnia is the currency of Ukraine and the zloty that of Poland.", 1),
(S, "What is the currency of Kenya?", ["Kenyan pound", "Birr", "Kenyan shilling", "Rand"], 2, "Kenya uses the Kenyan shilling (code KES).", "Ethiopia uses the birr and South Africa the rand.", 1),
(S, "What is the currency of Libya?", ["Libyan dinar", "Libyan pound", "Dirham", "Rial"], 0, "Libya uses the Libyan dinar (code LYD).", "The Libyan pound was replaced by the dinar in 1971.", 1),
(S, "What is the currency of Sri Lanka?", ["Taka", "Sri Lankan rupee", "Rufiyaa", "Ngultrum"], 1, "Sri Lanka uses the Sri Lankan rupee (code LKR).", "The taka is the currency of Bangladesh and the rufiyaa that of the Maldives.", 1),
(S, "What is the date of America's Independence Day?", ["4 July 1776", "4 July 1789", "14 July 1776", "1 January 1776"], 0, "The Declaration of Independence of the United States was adopted on 4 July 1776, which is celebrated as Independence Day.", "Americans celebrate it every year on 4 July.", 1),
(S, "On what date did Quaid-e-Azam Muhammad Ali Jinnah die?", ["14 August 1948", "11 September 1948", "25 December 1948", "11 August 1948"], 1, "Quaid-e-Azam died in Karachi on 11 September 1948, a little over a year after Pakistan was created.", "His death anniversary is observed on 11 September every year.", 1),
(S, "In which month and Hijri year did the conquest of Makkah (Fatah Makkah) take place?", ["Ramadan 8 AH", "Shawwal 3 AH", "Ramadan 2 AH", "Dhul Qadah 6 AH"], 0, "The Prophet (PBUH) entered Makkah with an army of about ten thousand in Ramadan 8 AH, traditionally dated 20 Ramadan.", "The conquest took place almost without bloodshed and the Prophet (PBUH) granted a general amnesty.", 2),
(S, "On which date was the Battle of Uhud fought?", ["17 Ramadan 2 AH", "7 Shawwal 3 AH", "5 Shawwal 5 AH", "20 Ramadan 8 AH"], 1, "The Battle of Uhud was fought on 7 Shawwal 3 AH (March 625 CE) near Mount Uhud, close to Madina.", "Hazrat Hamza (RA) was martyred in this battle.", 2),
(S, "On which date was the Battle of Badr fought?", ["7 Shawwal 3 AH", "17 Ramadan 2 AH", "10 Ramadan 8 AH", "1 Muharram 1 AH"], 1, "The Battle of Badr took place on 17 Ramadan 2 AH, the first major battle between Muslims and the Quraish.", "It is called Youm-ul-Furqan, the day of distinction between truth and falsehood.", 2),
(S, "On which date did Dr. Abdul Qadeer Khan die?", ["10 October 2021", "10 October 2020", "28 May 2021", "1 March 2022"], 0, "Dr. Abdul Qadeer Khan, known as the father of Pakistan's nuclear programme, died in Islamabad on 10 October 2021.", "He was awarded Nishan-e-Imtiaz and Hilal-e-Imtiaz.", 1),
(S, "When did the Quaid-e-Azam present his famous Fourteen Points?", ["March 1929", "March 1940", "December 1906", "November 1916"], 0, "Jinnah presented his Fourteen Points in Delhi in March 1929 in reply to the Nehru Report.", "The Lahore Resolution came later, in March 1940.", 1),
(S, "What name is given to 28 May, the day Pakistan carried out its nuclear tests in 1998?", ["Youm-e-Takbeer", "Youm-e-Istehsal", "Youm-e-Difa", "Youm-e-Pakistan"], 0, "Pakistan conducted its nuclear tests in the Chagai hills on 28 May 1998 and the day is observed as Youm-e-Takbeer.", "Pakistan became the seventh declared nuclear power.", 1),
(S, "What is the derivative of the exponential function e to the power x with respect to x?", ["e to the power x", "x times e to the power (x minus 1)", "Natural log of x", "One divided by x"], 0, "The function e^x is its own derivative, so d/dx of e^x equals e^x.", "The derivative of a to the power x is a^x times ln a.", 1),
(S, "What is the term of a Senator in Pakistan?", ["4 years", "3 years", "5 years", "6 years"], 3, "Senators are elected for a six-year term, and half retire every three years.", "The Senate itself is a permanent house and is never dissolved.", 2),
(S, "What is the duty of Hazrat Mikail (AS)?", ["Bringing revelation", "Blowing the Trumpet", "Taking souls", "Managing rain and sustenance"], 3, "Hazrat Mikail (AS) is the angel in charge of rain and the provision of sustenance.", "Hazrat Jibrail brings revelation, Israfil blows the Trumpet and Azrael takes souls.", 1),
(S, "What is the first month of the Islamic (Hijri) calendar?", ["Rabi-ul-Awwal", "Ramadan", "Muharram", "Rajab"], 2, "The Hijri calendar begins with Muharram, and 1 Muharram is the Islamic New Year.", "The calendar was introduced in the time of Hazrat Umar (RA) and counts from the Hijrah to Madina.", 2),
(S, "According to the Islamic teachings, which question is first asked from a person in the grave?", ["Who is your Lord?", "Did you pray?", "Did you fast?", "What is your name?"], 0, "Munkar and Nakir first ask the deceased: Who is your Lord (Man Rabbuka)? Then they ask about his religion and his Prophet.", "Salah is the first deed to be accounted for on the Day of Judgement.", 1),
(S, "On which date was the State Bank of Pakistan formally started?", ["1 July 1948", "14 August 1947", "1 January 1949", "7 October 1958"], 0, "The State Bank of Pakistan began functioning on 1 July 1948 and was inaugurated by Quaid-e-Azam.", "Before it, the Reserve Bank of India handled central banking for Pakistan for a short time.", 1),
]
